export type Side = "w" | "b";

export type ModelPlayers = {
  white: string;
  black: string;
  event?: string;
};

export type OpeningLine = {
  id: string;
  name: string;
  plies: string[];
  side: Side;
  /** Catalogue idea shown under the line name while training. */
  idea?: string;
  /** What happens after the book. Optional; the end modal falls back to idea. */
  next?: string;
  /**
   * End-of-line card. Optional. A blank or missing note shows no card.
   * Drill-pack line 1 notes live in line-explains.ts. Later lines can set this.
   */
  explain?: string;
  /**
   * Educational notes shown while training. The Slav preview sets these.
   * Other packs leave them unset.
   */
  drill?: {
    teach: string;
    watch: string;
    checkpoint: string;
    answer: string;
  };
  /** Named model game — who sat each side */
  players?: ModelPlayers;
};

export type Pack = {
  id: string;
  name: string;
  eco: string;
  side: "White" | "Black" | "Mixed";
  section: "white" | "black" | "special";
  /** Caro-Kann for Black is free while we check the rest — hidden packs stay in this file */
  isFree: boolean;
  /** Paid packs (everything except the currently visible free pack) */
  isPremium: boolean;
  /** Display price when paid; null when free */
  price: string | null;
  blurb: string;
  /** What the opening is, then what the pack drills. */
  about?: string;
  /** Collapsed card hint, e.g. "Free · 5 book lines + 3 traps" */
  closedLabel?: string;
  lines: OpeningLine[];
  /** Optional badge shown on the pack card (e.g. "Deep Lines") */
  badge?: string;
};

export type ComingSoon = { name: string; blurb: string };

